video.script:
// 播放页把真实地址直接拼在 player 容器的 iframe 初始化字符串里：
// document.getElementById('players').innerHTML = '<iframe src="/player/mui-player.php?标题,https://.../master.m3u8,下一页">'
// 取址策略（v2）：收集页面全部 m3u8/mp4 明文地址（排除播放器壳路径），按
// 「路径分辨率标签降序 + m3u8 优先」排序取最优，防止站点在同页埋多档地址时
// 取到低清（路径标签 1080/720 与真实码率无关，只作同页多候选间的相对依据）。
// 无明文地址时回退 player_aaaa 配置（含 encrypt 1/2 解码）。
function _hsAtob(s){var k='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';var o='';s=String(s).replace(/[^A-Za-z0-9+\/=]/g,'').replace(/=+$/,'');for(var i=0;i<s.length;i+=4){var a=k.indexOf(s.charAt(i)),b=k.indexOf(s.charAt(i+1)),c=i+2<s.length?k.indexOf(s.charAt(i+2)):-1,d=i+3<s.length?k.indexOf(s.charAt(i+3)):-1;if(c<0)c=0;if(d<0)d=0;o+=String.fromCharCode((a<<2)|(b>>4));if(i+2<s.length)o+=String.fromCharCode(((b&15)<<4)|(c>>2));if(i+3<s.length)o+=String.fromCharCode(((c&3)<<6)|d);}return o;}
function _hsPlayer(html){var i=html.indexOf('player_aaaa');if(i<0)return '';var k=html.indexOf('{',i);if(k<0)return '';var d=0,e=-1;for(var j=k;j<html.length;j++){var c=html.charAt(j);if(c=='{')d++;else if(c=='}'){d--;if(d==0){e=j+1;break;}}}if(e<0)return '';var cfg=JSON.parse(html.substring(k,e));var u=cfg.url||'';var enc=cfg.encrypt||0;if(enc==2){u=_hsAtob(u);try{u=decodeURIComponent(u);}catch(x){}}else if(enc==1){try{u=decodeURIComponent(u);}catch(x){}}return u;}
function _hsRes(u){var m=String(u).toLowerCase().match(/\/(4k|2160|1440|2k|1080|720|540|480|360|240)(?:p|kb)?\//);if(!m)return 0;var t={'4k':2160,'2160':2160,'2k':1440,'1440':1440,'1080':1080,'720':720,'540':540,'480':480,'360':360,'240':240};return t[m[1]]||0;}
function parseVideo(html){try{var all=html.match(/https?:\/\/[^"'\s,]+?\.(?:m3u8|mp4)[^"'\s,]*/g)||[];var cands=[];for(var i=0;i<all.length;i++){if(all[i].indexOf('/player/')<0)cands.push(all[i]);}if(cands.length){cands.sort(function(a,b){var ra=_hsRes(a),rb=_hsRes(b);if(ra!==rb)return rb-ra;var ha=a.indexOf('.m3u8')>=0?1:0,hb=b.indexOf('.m3u8')>=0?1:0;return hb-ha;});return cands[0];}var u=_hsPlayer(html);if(u&&u.indexOf('http')===0)return u;return '';}catch(e){return '';}}
